import{_ as a,c as e,o as p,a4 as t}from"./chunks/framework.4aTu-Nia.js";const _=JSON.parse('{"title":"YUV","description":"","frontmatter":{},"headers":[],"relativePath":"project/yuv.md","filePath":"project/yuv.md"}'),s={name:"project/yuv.md"},n=t(`<h1 id="yuv" tabindex="-1">YUV <a class="header-anchor" href="#yuv" aria-label="Permalink to &quot;YUV&quot;">​</a></h1><h2 id="yuv-压缩、传输" tabindex="-1">YUV 压缩、传输 <a class="header-anchor" href="#yuv-压缩、传输" aria-label="Permalink to &quot;YUV 压缩、传输&quot;">​</a></h2><p>YUV 过去是应用在电视领域，现在一般说的 YUV 是指应用于互联网领域的 YCbCr</p><p>亮度、色调、色饱和度</p><p>原始像素信息，不包含采样格式、宽高</p><p>可以降级成黑白</p><h2 id="rgb-用于显示器" tabindex="-1">RGB 用于显示器 <a class="header-anchor" href="#rgb-用于显示器" aria-label="Permalink to &quot;RGB 用于显示器&quot;">​</a></h2><p>显示器使用 RGB 发光</p><p>R/G/B 三个分量里都有高度信息</p><p><a href="https://ffmpeg.xianwaizhiyin.net/base-knowledge/raw-yuv.html" target="_blank" rel="noreferrer">YUV色彩空间 · FFmpeg原理</a></p><p>RGB 诉求于人眼对色彩的感应，YUV则着重于视觉对于亮度的敏感程度。因为人眼相比色度，对亮度更敏感。所以YUV对亮度的完全采样，色度的选择采样。即可在人眼察觉不到的范围内最大限度的压缩图像。色度抽样</p><h2 id="yuv420" tabindex="-1">YUV420 <a class="header-anchor" href="#yuv420" aria-label="Permalink to &quot;YUV420&quot;">​</a></h2><blockquote><p>经过大量研究实验表明，视觉系统 对 色度 的敏感度 是远小于 亮度的。所以可以对 色度 采用更小的采样率来压缩数据，对亮度采用正常的采样率即可</p></blockquote><p>视频使用广泛的 YUV420 格式</p><p>具体来说，YUV420表示：</p><ul><li>Y：亮度分量，表示图像的黑白信息。每个像素都有一个对应的Y值。</li><li>U和V：色度分量，表示图像的颜色信息。U和V分量的抽样比例比亮度分量低。</li></ul><p>在YUV420中，色度分量的抽样比例通常为4:2:0，这意味着对于每4个亮度采样点，只有2个对应的色度采样点。具体地，U和V分量的水平和垂直采样点数量都是亮度分量的一半。</p><p>YUV420的采样方式可以有效地减少颜色信息的存储和传输量，同时保持图像的视觉质量，适用于大多数视频应用。</p><p>422 格式，是第一第二个像素共享 一组UV，第三第四像素共享 一组 UV</p><p>YUV 4:4:4 跟 RGB24 一样，每个像素占 3 字节，图片宽高是 1920x1080 ，所以这个 yuv 图片的大小如下</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>SIZE=1920∗1080∗3</span></span>
<span class="line"><span>6075 Kb</span></span></code></pre></div><p>YUV 420 小一半，也需要 3037 kb</p><p>动画看起来流畅，需要一秒播放 24 张图片，1个小时的电影大小如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>3∗24∗60∗60=259200</span></span></code></pre></div><p>1小时的YUV420 的电影，需要 253G 空间来存储</p><p>H264 的压缩比 可以是 102:1，上面那个 253G 的YUV420电影，压缩之后只需 2.5G 存储空间</p>`,26),o=[n];function i(l,r,c,h,d,u){return p(),e("div",null,o)}const b=a(s,[["render",i]]);export{_ as __pageData,b as default};
